module baseline(input [63:0] remainder, divisor,
                output [63:0] result, output ge);
    wire [63:0] low_delta = (remainder & 64'h7fffffffffffffff)
                         - (divisor & 64'h7fffffffffffffff);
    assign ge = remainder[63] == divisor[63] ? !low_delta[63] : remainder[63];
    assign result = ge ? remainder - divisor : remainder;
endmodule
module fused(input [63:0] remainder, divisor,
             output [63:0] result, output ge);
    wire [64:0] delta = {1'b0, remainder} - {1'b0, divisor};
    assign ge = !delta[64];
    assign result = ge ? delta[63:0] : remainder;
endmodule
module miter(input [63:0] remainder, divisor, output equivalent);
    wire [63:0] original_result, fused_result;
    wire original_ge, fused_ge;
    baseline a(remainder, divisor, original_result, original_ge);
    fused b(remainder, divisor, fused_result, fused_ge);
    assign equivalent = original_result == fused_result && original_ge == fused_ge;
endmodule
